  {
   "@type": "Question",
   "name": "Why won't my Jindo potty inside?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Jindos are known for keeping their living space very clean, and once they learn \"potty happens outside\" they rarely change the rule. Checking territory by scent plays a part too."
   }
  },
  {
   "@type": "Question",
   "name": "Can a Jindo learn to use a pad indoors?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Some do, but many never use one. Try artificial grass by the door or on a balcony with a scent from the walk; if it doesn't take, more walks is the realistic answer."
   }
  },
  {
   "@type": "Question",
   "name": "Do Jindo mixes insist on going outside too?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Mixes with strong Jindo traits often do. Some rescues also learned to go on dirt or grass before adoption."
   }
  },
  {
   "@type": "Question",
   "name": "How many potty walks does an outdoor-only Jindo need?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Adults are commonly given 3–4 potty chances a day. At minimum go out first thing and before bed, and avoid days with more than 8 hours between chances."
   }
  }
 ]
